import type { KnowledgeNode, KnowledgeEdge, NodeType, NodeDetails } from '../types';

/**
 * The knowledge universe of Atlante.
 *
 * 250+ curated nodes spanning twenty-one civilizations, woven together by edges
 * that trace how ideas travel across time and place. Cross-civilization edges
 * (e.g. India's zero → Islamic algebra → Turing's machine) are deliberate:
 * they let the constellation reveal the evolution of ideas, and they power the
 * guided Story paths in `stories.ts`.
 *
 * Kept intentionally compact via the `n`/`e` builders so the dataset stays
 * readable and easy to extend toward the Neo4j / Wikidata phases.
 */

function n(
    id: string,
    label: string,
    type: NodeType,
    civilizationId: string | undefined,
    summary: string,
    details?: NodeDetails
): KnowledgeNode {
    return { id, label, type, civilizationId, summary, details };
}

function e(source: string, target: string, label?: string): KnowledgeEdge {
    return { source, target, label };
}

